        static bool Small=>Screen.width==1366;
        static async Task BagMode(MonsterInventoryController bag,VisualElement ui,bool list){if((bool)Get(bag,"listView")!=list){await Task.Delay(180);BagVerification.Click(ui,"inventory-view-button");await Task.Delay(200);}Check((bool)Get(bag,"listView")==list,"capture mode is "+(list?"list":"grid"));}
        static void Header(VisualElement ui,string rootName,string backName){var root=ui.Q(rootName);var back=root.Q<Button>(backName);var picked=back.panel.Pick(back.worldBound.center);Check(picked==back||back.Contains(picked),rootName+" Back center picks button or its descendant");
            float scale=Screen.width/ui.worldBound.width,s=Mathf.Min(Screen.width/1600f,Screen.height/900f);var b=back.worldBound;var expected=UnifiedPanelHeader.Back;float ox=(Screen.width-1600*s)/2,oy=(Screen.height-900*s)/2;
            Check(Mathf.Abs(b.x*scale-(ox+expected.x*s))<2&&Mathf.Abs(b.y*scale-(oy+expected.y*s))<2&&Mathf.Abs(b.width*scale-expected.width*s)<2,rootName+" Back matches shared bounds at "+Screen.width);
            var caption=back.Q<Label>("unified-back-caption");Check(Mathf.Abs(caption.resolvedStyle.fontSize-21)<.1f,rootName+" Back font is logical 21");var face=back.Q<UnifiedPanelSurface>();var before=back.worldBound;face.HoverAmount=1;face.PressAmount=1;face.Focused=true;face.MarkDirtyRepaint();Check(before==back.worldBound,rootName+" feedback does not alter geometry");face.HoverAmount=face.PressAmount=0;face.Focused=false;face.MarkDirtyRepaint();}
        static async Task PetChecks(GameMenuController menu,VisualElement ui){var party=Object.FindFirstObjectByType<PetPartyPanelController>();var panel=ui.Q("pets-panel");Check(panel.resolvedStyle.opacity==1&&panel.resolvedStyle.backgroundColor.a==1,"Pet root is opaque; content opacity remains 1");
            Check(ui.Q("pets-party-row").Children().OfType<AngularButton>().Count()==6,"Pet retains six roster slots");Check(!party.IsPreview3D,"Pet defaults to 2D");Check(ui.Q<AngularSurface>("pets-selected-portrait").Art==null,"missing hero art does not reuse slot avatar");
            foreach(string tab in new[]{"skills","growth","overview"}){BagVerification.Click(ui,"pets-tab-"+tab);await Task.Delay(220);Check(ui.Q("pets-tab-"+tab).ClassListContains("is-selected"),"Pet tab callback "+tab);if(Small&&tab!="overview")await Shot(ui,"pet-"+tab);}
            var beforeSlots=Object.FindFirstObjectByType<PetCommandHudProvider>().GetPetSlots().Select(p=>p.summoned).ToArray();var roster=ui.Q("pets-party-row").Children().OfType<AngularButton>().ToArray();var other=roster.FirstOrDefault(b=>!b.ClassListContains("is-empty")&&!b.ClassListContains("is-selected"));if(other!=null){await Task.Delay(180);typeof(Clickable).GetMethod("Invoke",Any).Invoke(other.clickable,new object[]{null});await Task.Delay(180);Check(beforeSlots.SequenceEqual(Object.FindFirstObjectByType<PetCommandHudProvider>().GetPetSlots().Select(p=>p.summoned)),"viewing a roster avatar does not summon");}
            BagVerification.Click(ui,"pets-mode-3d");await Task.Delay(450);Check(party.IsPreview3D&&party.HasPreviewTexture,"3D allocates only on explicit request");BagVerification.Click(ui,"pets-mode-2d");await Task.Delay(250);Check(!party.HasPreviewTexture,"3D preview releases on return to 2D");
            BagVerification.Click(ui,"pets-details-button");await Task.Delay(180);Check(party.IsDetailsOpen,"Pet details popup still opens");menu.HandleShortcut(KeyCode.Escape);await Task.Delay(180);Check(!party.IsDetailsOpen,"Esc dismisses details before closing Pet");
            if(Small)await OpaquePet(ui);
        }
        static async Task OpaquePet(VisualElement ui){var cameras=Object.FindObjectsByType<Camera>(FindObjectsSortMode.None).Where(c=>c.enabled&&c.targetTexture==null).ToArray();var flags=cameras.Select(c=>c.clearFlags).ToArray();var masks=cameras.Select(c=>c.cullingMask).ToArray();var colors=cameras.Select(c=>c.backgroundColor).ToArray();
            try{for(int pass=0;pass<2;pass++){for(int i=0;i<cameras.Length;i++){cameras[i].clearFlags=CameraClearFlags.SolidColor;cameras[i].cullingMask=0;cameras[i].backgroundColor=pass==0?Color.magenta:Color.green;}await Shot(ui,"pet-world-"+(pass==0?"magenta":"green"));}log.Add("OPAQUE A/B actual enabled camera clears changed to magenta/green; pixel samples compared externally.");}finally{for(int i=0;i<cameras.Length;i++){cameras[i].clearFlags=flags[i];cameras[i].cullingMask=masks[i];cameras[i].backgroundColor=colors[i];}}}
        static async Task BagChecks(GameMenuController menu,MonsterInventoryController bag,VisualElement ui){var button=ui.Q<Button>("cancel-button");Check(ReferenceEquals(button,Get(bag,"cancelButton"))&&ReferenceEquals(ui,Get(bag,"controlsRoot"))&&(bool)Get(bag,"controlsRegistered"),"Bag cache/root registration current");Check(ui.Query<Button>("cancel-button").ToList().Count==1,"Bag has exactly one cancel button");
            var selected=bag.SelectedItem;var filter=ui.Q<DropdownField>("inventory-filter-field");string filterValue=filter.value;BagVerification.Click(ui,"inventory-view-button");await Task.Delay(180);Check(bag.SelectedItem==selected&&filter.value==filterValue,"Bag grid/list preserves selection and filter");BagVerification.Click(ui,"inventory-view-button");await Task.Delay(180);
            var search=ui.Q<TextField>("inventory-search-field");string original=search.value;search.value="__qa_no_item_matches__";await Task.Delay(180);Check(!ui.Q("item-grid").Children().Any(Visible),"Bag search hides all pooled item cards");if(Small)await Shot(ui,"bag-empty-search");search.value=original;await Task.Delay(180);
            var choice=typeof(BagPresentation).Assembly.GetType("Capstone.Game.Inventory.Bag.BagChoicePopup");var statics=System.Reflection.BindingFlags.Static|System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Public;choice.GetMethod("Show",statics).Invoke(null,new object[]{filter});await Task.Delay(180);Check((bool)choice.GetMethod("OwnsKey",statics).Invoke(null,new object[]{ui}),"Bag dropdown owns input while open");choice.GetMethod("Close",statics,null,new[]{typeof(VisualElement)},null).Invoke(null,new object[]{ui});await Task.Delay(200);Check(!(bool)choice.GetMethod("OwnsKey",statics).Invoke(null,new object[]{ui}),"Bag dropdown releases input when closed");
            button.Focus();await Task.Delay(180);var input=Object.FindFirstObjectByType<InventoryInputController>();bool handled=(bool)Call(input,"TryHandleKey",KeyCode.Return);await Task.Delay(180);Check(handled&&!bag.IsOpen&&menu.CurrentMode==GameInputMode.Menu,"focused Bag Back Return through existing input router closes to Menu");menu.OpenInventoryDirect();await Task.Delay(200);
            for(int i=0;i<2;i++){int count=0;Action observer=()=>count++;bag.BackRequested+=observer;try{await Task.Delay(180);BagVerification.Click(ui,"cancel-button");await Task.Delay(180);Check(count==1&&!bag.IsOpen&&menu.CurrentMode==GameInputMode.Menu,"Bag Back callback closes once to Menu, cycle "+i);}finally{bag.BackRequested-=observer;}
                menu.OpenInventoryDirect();await Task.Delay(200);var picked=button.panel.Pick(button.worldBound.center);Check(picked==button||button.Contains(picked),"Bag Back remains pickable after reopen "+i);}
        }
        static void QuestTab(QuestPanelController q,string value)=>Call(q,"SelectTab",Enum.Parse(Get(q,"currentTab").GetType(),value));
        static async Task QuestChecks(GameMenuController menu,QuestPanelController q,VisualElement ui){var manager=Object.FindFirstObjectByType<QuestManager>();var states=(List<QuestRuntimeState>)Get(manager,"activeQuests");var originals=states.ToArray();var original=states.First(s=>s?.Definition!=null);int index=states.IndexOf(original);var definition=original.Definition;
            try{foreach(string id in new[]{"progress","main","side","event","other"}){BagVerification.Click(ui,"quest-tab-"+id);await Task.Delay(180);Check(ui.Q("quest-tab-"+id).ClassListContains("is-selected"),"Quest category "+id+" retained");}
                var active=new QuestRuntimeState(definition,Time.time);active.SetRewardsClaimed(true);states[index]=active;QuestTab(q,"Main");Call(q,"RefreshAll");Call(q,"SelectQuest",active);await Task.Delay(180);var before=ui.Q("quest-detail-column").worldBound;Check(!active.IsTracked,"Quest select does not auto-track");BagVerification.Click(ui,"track-quest-button");await Task.Delay(180);Check(active.IsTracked&&q.SelectedQuest==active&&before==ui.Q("quest-detail-column").worldBound,"tracking retains selection and does not move body");Check(!Visible(ui.Q("abandon-quest-button")),"official Cube cannot be abandoned");Check(!Visible(ui.Q("quest-progress-bar")),"Quest overall bar remains hidden");if(Small)await Shot(ui,"quest-active");
                var receiver=Get(q,"showOnMapRequested");try{Set(q,"showOnMapRequested",null);Call(q,"RefreshActionButtons");Check(Visible(ui.Q("show-map-button"))&&!ui.Q<Button>("show-map-button").enabledInHierarchy,"map without receiver stays disabled");}finally{Set(q,"showOnMapRequested",receiver);Call(q,"RefreshActionButtons");}
                if(Small){bool delivered=false;Action<Vector3> observer=_=>delivered=true;q.ShowOnMapRequested+=observer;try{await Task.Delay(180);BagVerification.Click(ui,"show-map-button");await Task.Delay(220);Check(delivered&&menu.CurrentMode==GameInputMode.WorldMap,"real Quest map connector receives target and opens WorldMap");}finally{q.ShowOnMapRequested-=observer;menu.OpenQuestDirect();QuestTab(q,"Main");Call(q,"SelectQuest",active);}}
                var detail=ui.Q<ScrollView>("quest-detail-scroll");var clone=Object.Instantiate(definition);try{Set(clone,"description",string.Join("\n",Enumerable.Repeat(definition.Description,15)));Set(clone,"title",string.Join(" ",Enumerable.Repeat(definition.Title,15)));var longState=new QuestRuntimeState(clone,Time.time);longState.SetRewardsClaimed(true);states[index]=longState;QuestTab(q,"Main");Call(q,"RefreshAll");Call(q,"SelectQuest",longState);await Task.Delay(200);Check(ui.Q<Label>("quest-detail-title").tooltip==clone.Title,"long title retains full tooltip");detail.ScrollTo(ui.Q("quest-actions"));await Task.Delay(180);Check(ui.Q("quest-actions").worldBound.yMax<=detail.contentViewport.worldBound.yMax+2,"long Quest content scrolls to its actions");}finally{Object.Destroy(clone);}
                if(Small){var service=Object.FindFirstObjectByType<QuestRewardService>();var saves=Get(service,"saveController");string failedId=service.LastFailedQuestId,message=service.LastFailureMessage;var failed=new QuestRuntimeState(definition,new QuestRuntimeSaveData{questId=original.QuestId,status=QuestStatus.Completed,rewardsClaimed=false});states[index]=failed;Call(q,"RefreshAll");Call(q,"SelectQuest",failed);try{Set(service,"saveController",null);Call(service,"HandleRewardsReady",failed,definition.Rewards);Check(!string.IsNullOrEmpty(service.LastFailureMessage)&&ui.Q<Label>("quest-reward-feedback").text==service.LastFailureMessage&&Visible(ui.Q("quest-reward-feedback")),"Quest displays actual reward-service failure feedback");}finally{Set(service,"saveController",saves);Set(service,"<LastFailedQuestId>k__BackingField",failedId);Set(service,"<LastFailureMessage>k__BackingField",message);failed.SetRewardsClaimed(true);}}
            }finally{states.Clear();states.AddRange(originals);Call(q,"RefreshAll");foreach(var tracker in Object.FindObjectsByType<QuestTrackerHudController>(FindObjectsSortMode.None))Call(tracker,"RefreshTrackedQuest");}
        }
        static async Task ProfileChecks(ProfilePanelController profile,VisualElement ui){var root=(RectTransform)Get(profile,"root");var screen=(RectTransform)Get(profile,"designSurface");Check(((Array)Get(profile,"teamSlots")).Length==6,"Profile keeps six avatar-only slots");Check(screen.Find("StatsOverviewPanel").Cast<Transform>().Count(t=>t.name.StartsWith("StatsCard_"))==6,"Profile retains six statistic cards");
            var provider=(IPlayerProfileProvider)Get(profile,"provider");string name=provider.GetSnapshot().DisplayName;int avatar=provider.SelectedAvatarIndex;
            try{Call(profile,"ShowNameDialog");var field=(UnityEngine.UI.InputField)Get(profile,"nameInput");field.text=" A ";Call(profile,"ConfirmNameChange");await Task.Delay(180);Check(!string.IsNullOrEmpty(((UnityEngine.UI.Text)Get(profile,"nameError")).text),"Profile rename trims and rejects one character");if(Small)await ProfileShot(profile,"profile-rename-error");field.text=new string('A',20);await Task.Delay(180);Call(profile,"ConfirmNameChange");await Task.Delay(180);Check(provider.GetSnapshot().DisplayName==new string('A',20),"Profile accepts 20 characters through existing UI");provider.TrySetDisplayName(name,out _);
                Call(profile,"ShowAvatarDialog");await Task.Delay(180);Check(((RectTransform)Get(profile,"avatarDialog")).gameObject.activeSelf,"Profile avatar picker still opens");if(Small)await ProfileShot(profile,"profile-avatar-picker");int next=Enumerable.Range(0,provider.AvatarOptions.Count).FirstOrDefault(i=>provider.AvatarOptions[i]!=null&&i!=avatar);if(provider.AvatarOptions.Count>0&&provider.AvatarOptions[next]!=null){Call(profile,"SelectAvatar",next);await Task.Delay(180);Check(provider.SelectedAvatarIndex==next,"avatar selection applies immediately");}
            }finally{provider.TrySetDisplayName(name,out _);provider.TrySelectAvatar(avatar);Call(profile,"HideNameDialog");Call(profile,"HideAvatarDialog");Call(profile,"Refresh");}
        }
        static async Task ProfileAll(GameMenuController menu,MonsterInventoryController bag,ProfilePanelController profile){var handles=new List<ProfilerRecorderHandle>();ProfilerRecorderHandle.GetAvailable(handles);var available=handles.Select(h=>new{h,d=ProfilerRecorderHandle.GetDescription(h)}).ToArray();var recorders=new List<ProfilerRecorder>();var names=new List<string>();var csv=new List<string>();
            try{foreach(string marker in new[]{"Main Thread","GC Allocated In Frame","UIElements.UpdateLayout","UIElements.UpdateRenderData","UIR.DrawChain","Canvas.BuildBatch"}){var found=available.FirstOrDefault(x=>x.d.Name==marker);if(found==null){log.Add("COUNTER UNAVAILABLE "+marker);continue;}var recorder=new ProfilerRecorder(found.h,1,ProfilerRecorderOptions.StartImmediately|ProfilerRecorderOptions.WrapAroundWhenCapacityReached|ProfilerRecorderOptions.SumAllSamplesInFrame);recorders.Add(recorder);names.Add(marker+" ["+found.d.UnitType+"]");}csv.Add("panel,frame,"+string.Join(",",names));
                double end=Time.realtimeSinceStartupAsDouble+16;foreach(string panel in new[]{"Pet","Bag","Quest","Profile"}){bag.Close();profile.Close();await Task.Delay(200);if(panel=="Pet")menu.OpenPetsDirect();else if(panel=="Bag")menu.OpenInventoryDirect();else if(panel=="Quest")menu.OpenQuestDirect();else menu.OpenProfileDirect();await Task.Delay(250);int previous=-1;for(int sample=0;sample<30&&Time.realtimeSinceStartupAsDouble<end;){await Task.Delay(16);if(Time.frameCount==previous)continue;previous=Time.frameCount;csv.Add(panel+","+previous+","+string.Join(",",recorders.Select(r=>r.LastValue)));sample++;}}
                File.WriteAllLines(Root+"profiler-editor.csv",csv);log.Add("PROFILER actual Editor samples "+(csv.Count-1)+"; maximum 16 seconds; markers include the whole frame, not Quest/Bag-only cost.");
            }finally{foreach(var recorder in recorders)recorder.Dispose();}File.WriteAllLines(Root+"checks.txt",log);}
        static async Task Native(GameMenuController menu,MonsterInventoryController bag,VisualElement ui,string phase){menu.OpenMenu();await Task.Delay(200);menu.OpenInventoryDirect();await Task.Delay(250);if(bag.SelectedItem==null)bag.SelectNextItem();if(phase.Contains("list")){BagVerification.Click(ui,"inventory-view-button");await Task.Delay(200);}var back=ui.Q<Button>("cancel-button");back.Focus();var events=new List<string>{"utc,event,target"};int count=0,captures=0;void Frame(){ui.schedule.Execute(()=>ScreenCapture.CaptureScreenshot(Root+"native-frame-"+(captures++%10).ToString("D2")+".png")).StartingIn(180);}Action closed=()=>{count++;events.Add(DateTime.UtcNow.ToString("O")+",BackRequested,"+count);Frame();};
            EventCallback<PointerDownEvent> pointer=e=>{events.Add(DateTime.UtcNow.ToString("O")+",PointerDown,"+PathOf(e.target as VisualElement));Frame();};EventCallback<KeyDownEvent> key=e=>{events.Add(DateTime.UtcNow.ToString("O")+",KeyDown,"+e.keyCode);Frame();};ui.RegisterCallback(pointer,TrickleDown.TrickleDown);ui.RegisterCallback(key,TrickleDown.TrickleDown);bag.BackRequested+=closed;File.WriteAllText(Root+"native-status.txt","READY "+phase+"; focused cancel-button; maximum 600 seconds /10 rolling captures");
            try{double end=Time.realtimeSinceStartupAsDouble+600;while(Time.realtimeSinceStartupAsDouble<end&&!File.Exists(Root+"native.stop")){File.WriteAllLines(Root+"native-events.csv",events.Take(1000));File.WriteAllText(Root+"native-state.txt","open="+bag.IsOpen+" mode="+menu.CurrentMode+" backCount="+count);await Task.Delay(200);}}
            finally{ui.UnregisterCallback(pointer,TrickleDown.TrickleDown);ui.UnregisterCallback(key,TrickleDown.TrickleDown);bag.BackRequested-=closed;if(File.Exists(Root+"native.stop"))File.Delete(Root+"native.stop");File.WriteAllText(Root+"native-status.txt","STOPPED");}
        }
    }
